import unittest
import monthly_sales

class MonthlySalesTests(unittest.TestCase):
    def test_empty(self):
        records = []
        self.assertEqual(monthly_sales.run(records=records), {"groups": [], "total_cents": 0, "record_count": 0})

    def test_group_sort_refunds_zero_and_count(self):
        records = [
            {"year": 2025, "month": 2, "region": "West", "amount_cents": 0},
            {"year": 2024, "month": 12, "region": "East", "amount_cents": 500},
            {"year": 2025, "month": 2, "region": "West", "amount_cents": -125},
            {"year": 2025, "month": 1, "region": "West", "amount_cents": 300},
        ]
        self.assertEqual(monthly_sales.run(records=records), {
            "groups": [
                {"year": 2024, "month": 12, "region": "East", "total_cents": 500, "count": 1},
                {"year": 2025, "month": 1, "region": "West", "total_cents": 300, "count": 1},
                {"year": 2025, "month": 2, "region": "West", "total_cents": -125, "count": 2},
            ],
            "total_cents": 675,
            "record_count": 4,
        })

if __name__ == "__main__":
    unittest.main()
